mapper.select:
SELECT * FROM customers
WHERE business_id = #{businessId}
ORDER BY created_at DESC

SELECT * FROM customers
WHERE business_id = #{businessId}
  AND phone = #{phone}

SELECT EXISTS(
    SELECT 1 FROM customers
    WHERE business_id = #{businessId} AND phone = #{phone}
)

SELECT EXISTS(
    SELECT 1 FROM customers
    WHERE business_id = #{businessId} AND id = #{id}
)

SELECT COUNT(*)
FROM customers
WHERE business_id = #{businessId}
  AND created_at BETWEEN #{startDateTime} AND #{endDateTime}

SELECT * FROM customers
WHERE user_id = #{userId}
  AND business_id = #{businessId}

SELECT COUNT(*)
FROM customers
WHERE business_id = #{businessId}
  AND birth_date IS NOT NULL
  AND EXTRACT(MONTH FROM birth_date) = #{month}
  AND EXTRACT(DAY FROM birth_date) = #{day}

SELECT COUNT(*)
FROM customers
WHERE business_id = #{businessId}
  AND visit_count BETWEEN #{minVisits} AND #{maxVisits}

SELECT * FROM customers
WHERE name = #{name}
  AND phone = #{phone}
